-- Backs the Idempotency-Key header on POST /orders. Keys are scoped per
-- account; orders created without a key store NULL, which never conflicts.
-- CREATE INDEX CONCURRENTLY cannot run inside a transaction block.
ALTER TABLE orders ADD COLUMN idempotency_key text;
CREATE UNIQUE INDEX CONCURRENTLY orders_account_id_idempotency_key ON orders (account_id, idempotency_key);

