const express = require("express");
const db = require("../db");

const router = express.Router();

// A user may only modify their own account, so the id in the path must match
// the session's account. A mismatch matches no row and returns 404.
router.patch("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 AND deleted_at IS NULL RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 AND deleted_at IS NULL RETURNING id",
    [req.params.id, req.user.accountId]);
  if (!row) return res.status(404).end();
  res.status(204).end();
});

module.exports = router;

routes/orders.js.text:
const express = require("express");
const db = require("../db");

const router = express.Router();

// An optional Idempotency-Key header makes retries safe: a repeat with the same
// key returns the order the first request created instead of inserting another.
// Reusing a key with a different sku or quantity matches no row and returns 422.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  if (key && key.length > 255) return res.status(400).end();
  const row = await db.write(
    `INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4)
     ON CONFLICT (account_id, idempotency_key) DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
     WHERE orders.sku = EXCLUDED.sku AND orders.quantity = EXCLUDED.quantity
     RETURNING *`,
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (!row) return res.status(422).end();
  res.status(201).json(row);
});

// Scoped to the session's account; another account's order id matches no row
// and returns 404.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

