const db = require("../db");

const router = express.Router();

// An optional Idempotency-Key header makes retries safe: keys are unique per
// account, so a repeated key returns the order it first created instead of
// inserting another. A concurrent insert with the same key blocks on the
// unique index until the first commits, then falls through to the lookup.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  if (key && key.length > 255) return res.status(400).end();

