  const [existing] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, key]
  );
  // Reusing a key for a different order is a client bug, not a retry.
  if (existing.sku !== req.body.sku || String(existing.quantity) !== String(req.body.quantity)) {
    return res.status(422).end();
  }
  res.status(201).json(existing);
