const express = require("express");
const db = require("../db");

const router = express.Router();

// A client can send an Idempotency-Key header so that a retried POST returns
// the order the first attempt created instead of creating a second one. Keys
// are scoped to the account, so one account's key never matches another's order.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key");
  if (key !== undefined && (key.length === 0 || key.length > 255)) return res.status(400).end();

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key === undefined ? null : key]
  );
  if (row) return res.status(201).json(row);

  // The key was already used. Replay the original order, unless this request
  // asks for something different under the same key.
  const [existing] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, key]
  );
  if (String(existing.sku) !== String(req.body.sku) || String(existing.quantity) !== String(req.body.quantity)) {
    return res.status(422).end();
  }
  res.json(existing);
});

// Scoped to the caller's account; another account's order id gets 404.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

