const db = require("./db");

// Resolves the session cookie to its user and account. Every request that
// reaches a route handler has passed through here, so this is where a
// soft-deleted account (deleted_at set) loses access: its sessions stop
// resolving.
async function sessionUser(req, res, next) {
  const rows = await db.query(
    "SELECT u.id, u.email, u.account_id FROM sessions s JOIN users u ON u.id = s.user_id JOIN accounts a ON a.id = u.account_id WHERE s.token = $1 AND s.expires_at > now() AND a.deleted_at IS NULL",
    [req.cookies && req.cookies.session]
  );
  if (!rows.length) return res.status(401).end();
  req.user = { id: rows[0].id, email: rows[0].email, accountId: rows[0].account_id };
  next();
}

module.exports = { sessionUser };

logging.js.text:
// Writes one JSON line per request when the response closes. Mounted first in
// app.js so requests rejected by express.json() or sessionUser are logged too;
// req.user is read at close time, after sessionUser has set it. Bodies and
// cookies are never logged.
function requestLog(req, res, next) {
  const start = process.hrtime.bigint();
  res.on("close", () => {
    // A response that never finished was abandoned by the client (or timed
    // out) before the handler replied, so its statusCode is meaningless.
    const finished = res.writableFinished;
    console.log(JSON.stringify({
      time: new Date().toISOString(),
      method: req.method,
      path: req.originalUrl,
      status: finished ? res.statusCode : null,
      aborted: !finished,
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user ? req.user.id : null,
      accountId: req.user ? req.user.accountId : null,
    }));
  });
  next();
}

module.exports = { requestLog };

