const express = require("express");
const db = require("../db");

const router = express.Router();

// A user may only touch their own account. The account_id check lives in the
// WHERE clause so a foreign id matches no row and gets the same 404 as a
// nonexistent one.
router.patch("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 AND deleted_at IS NULL RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 AND deleted_at IS NULL RETURNING id",
    [req.params.id, req.user.accountId]);
  if (!row) return res.status(404).end();
  res.status(204).end();
});

module.exports = router;

routes/orders.js.text:
const express = require("express");
const db = require("../db");

const router = express.Router();

// An optional Idempotency-Key header makes retries safe: a repeat of the same
// request returns the original order instead of inserting a duplicate. Keys
// are unique per account via the (account_id, idempotency_key) index; requests
// without one behave as before, since NULL keys never conflict.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  if (key && key.length > 255) return res.status(400).end();
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (row) return res.status(201).json(row);

  // The key is taken. Replay the original order if this is the same request;
  // reusing a key for a different order is a client error.
  const [{ same_request, ...existing }] = await db.query(
    "SELECT *, (sku = $3 AND quantity = $4) AS same_request FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, key, req.body.sku, req.body.quantity]
  );
  if (!same_request) return res.status(422).end();
  res.status(201).json(existing);
});

// Scoped to the caller's account in the WHERE clause; another account's order
// matches no row and gets the same 404 as a nonexistent one.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

