logging.js.text:
// Logs one JSON line per request when its response closes. Mounted ahead of
// sessionUser so rejected (401) requests are logged too. Bodies and cookies are
// never logged: they carry session tokens and billing emails.
function requestLogger(req, res, next) {
  const start = process.hrtime.bigint();
  // Captured now because mounted routers rewrite req.url while handling.
  const path = req.path;
  res.on("close", () => {
    console.log(JSON.stringify({
      method: req.method,
      path,
      status: res.writableFinished ? res.statusCode : "aborted",
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
}

module.exports = { requestLogger };

