const express = require("express");
const db = require("../db");

const router = express.Router();

// Clients may send an Idempotency-Key header. A retry with the same key gets
// the order the first request created instead of a new one. Keys are unique
// per account; requests without one are never deduplicated.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (row) return res.status(201).json(row);

  // The key was already used. This runs as a separate statement so it sees a
  // conflicting order committed by a concurrent request with the same key.
  // Reusing a key for a different order is a client error.
  const [existing] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2 AND sku = $3 AND quantity = $4",
    [req.user.accountId, key, req.body.sku, req.body.quantity]
  );
  if (!existing) return res.status(422).end();
  res.status(201).json(existing);
});

// Scoped to the caller's account, so another account's order id matches no
// row and gets a 404.
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

